// Decodifica o PNG e analisa brilho por regiões para validar o render
const fs = require('fs'), zlib = require('zlib');
const buf = fs.readFileSync('/tmp/opencode/doom_shot1.png');
// parse chunks
let pos = 8, w, h, idat = [];
const readChunk = () => {
  const len = buf.readUInt32BE(pos); const type = buf.toString('ascii', pos+4, pos+8);
  const data = buf.subarray(pos+8, pos+8+len); pos += 12+len; return {type, data};
};
while (pos < buf.length) { const {type, data} = readChunk();
  if (type==='IHDR'){ w=data.readUInt32BE(0); h=data.readUInt32BE(4);} else if (type==='IDAT') idat.push(data);
  else if (type==='IEND') break; }
const raw = zlib.inflateSync(Buffer.concat(idat));
const stride = w*3+1; // bitdepth 8, 3 channels, filter byte per row
const rgb = Buffer.alloc(w*h*3);
let prev = Buffer.alloc(w*3);
for (let y=0;y<h;y++){
  const ft = raw[y*stride]; const row = raw.subarray(y*stride+1, y*stride+1+w*3);
  const out = Buffer.alloc(w*3);
  for (let x=0;x<w;x++){
    const a=row[x*3],b=row[x*3+1],c=row[x*3+2];
    let pa=0,pb=0,pc=0, la=0,lb=0,lc=0, ua=0,ub=0,uc=0;
    la = prev[x*3]; pb=prev[x*3+1]; lc=prev[x*3+2];
    if(x>0){ ua=out[x*3-3]; ub=out[x*3-2]; uc=out[x*3-1]; }
    let ra,rb,rc;
    if(ft===1){ra=(a+la)&255;rb=(b+lb)&255;rc=(c+lc)&255;}
    else if(ft===2){ra=(a+ua)&255;rb=(b+ub)&255;rc=(c+uc)&255;}
    else if(ft===3){ra=(a+((la+ua)>>1))&255;rb=(b+((lb+ub)>>1))&255;rc=(c+((lc+uc)>>1))&255;}
    else if(ft===4){
      const p=la+ua-pa; const paB=Math.abs(p-la),pbB=Math.abs(p-ua),pcB=Math.abs(p-pa);
      const pr = (paB<=pbB&&paB<=pcB)?la:(pbB<=pcB?ua:pa);
      ra=(a+pr)&255;rb=(b+pr)&255;rc=(c+pr)&255;
    } else {ra=a;rb=b;rc=c;}
    out[x*3]=ra;out[x*3+1]=rb;out[x*3+2]=rc;
  }
  out.copy(rgb, y*w*3); prev=out;
}
function avg(x0,y0,x1,y1){let s=0,n=0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const i=(y*w+x)*3;s+=(rgb[i]+rgb[i+1]+rgb[i+2])/3;n++;}return (s/n).toFixed(1);}
function hue(x0,y0,x1,y1){ // average channel
  let r=0,g=0,b=0,n=0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const i=(y*w+x)*3;r+=rgb[i];g+=rgb[i+1];b+=rgb[i+2];n++;}return `${(r/n).toFixed(0)},${(g/n).toFixed(0)},${(b/n).toFixed(0)}`;}
console.log('Canvas dims:', w,'x',h);
console.log('-- Regiões (brilho médio / RGB médio) --');
console.log('Teto (0,0 a w,80):   ', avg(0,0,w,80), ' RGB', hue(0,0,w,80));
console.log('Chao (0,120 a w,242):', avg(0,120,w,242), ' RGB', hue(0,120,w,242));
console.log('HUD bar (0,242 a w,300):', avg(0,242,w,300), ' RGB', hue(0,242,w,300));
console.log('Centro-arma (200,150 a 280,250):', avg(200,150,280,250), ' RGB', hue(200,150,280,250));
// Detecta presença de brilho vermelho (inimigo/vida) e verde (HUD)
let red=0,green=0, total=0;
for(let i=0;i<rgb.length;i+=1){ total++;
  const r=rgb[i],g=rgb[i+1],b=rgb[i+2];
  if(r>120 && r>2*g) red++; if(g>120 && g>r*1.1) green++;}
console.log('Pixels quentes vermelhos:', red, 'verdes:', green);
EOF

