import re
src = open('index.html', encoding='utf-8').read()
js = re.search(r'<script>(.*)</script>', src, re.S).group(1)
# Inserir HEAD/body mínimo + jogo + sonda
probe_html = src.replace('</body>','''
<script>
// === SONDA DE VERIFICAÇÃO (captura interna de pixels) ===
function sampleProbe() {
  const cv = document.getElementById("view");
  const g = cv.getContext("2d");
  const W2 = cv.width, H2 = cv.height;
  const gd = g.getImageData(0, 0, W2, H2).data;
  function px(x,y){ const i=(y*W2+x)*4; return [gd[i],gd[i+1],gd[i+2],gd[i+3]]; }
  function avg(x0,y0,x1,y1){ let r=0,g=0,b=0,n=0; for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const p=px(x,y);r+=p[0];g+=p[1];b+=p[2];n++;} return [Math.round(r/n),Math.round(g/n),Math.round(b/n)]; }
  // chave: usamos variáveis globais do jogo (W, H, VIEW_H, HUD, player, enemies, ammo, kills, ctx)
  const report = {
    "teto_top": avg(10,10,100,40),
    "chao_baixo": avg(10,VIEW_H-50,100,VIEW_H-10),
    "hud_face": px(20, VIEW_H + 20),
    "hud_centro": avg(90, VIEW_H+20, 200, VIEW_H+40),
    "centro_arma": avg(W/2-20, VIEW_H-90, W/2+20, VIEW_H-50),
    "player_pos": [player.x, player.y],
    "player_dir": [player.dirX.toFixed(2), player.dirY.toFixed(2)],
    "enemies": enemies.map(e=>({x:e.x,y:e.y,hp:e.hp,dead:e.dead})),
    "ammo": ammo, "kills": kills, "hp": player.hp, "gameOver": gameOver,
    "zbuf_centro": zbuffer[Math.floor(W/2)] ? zbuffer[Math.floor(W/2)].toFixed(2) : null,
  };
  document.getElementById("PROBE_OUT").textContent = JSON.stringify(report);
}
setTimeout(sampleProbe, 1500);
setTimeout(()=>{ // segunda amostra pós movimento simulado?
  sampleProbe();
}, 3000);
</script>
<div id="PROBE_OUT" style="display:none"></div>
''' + '</body>')
open('/tmp/opencode/probe.html','w',encoding='utf-8').write(probe_html)
print("probe.html escrito")
