// AUDITORIA RIGOROSA do motor — testes unitários das funções puras
const src = require('fs').readFileSync('index.html','utf8');
const js = src.match(/<script>([\s\S]*)<\/script>/)[1];

// Extrai apenas o que é testável em node (mapa + colisão) simulando um contexto mínimo
const sandbox = {};
const ctxStub = new Proxy({}, { get: (t,p) => { if(p==='canvas') return null; return (...a)=>{} }, set: () => true });
const docStub = { createElement: () => { const c = { width:0, height:0, getContext:()=>ctxStub }; return c; }, getElementById: () => null };
const winStub = { addEventListener:()=>{}, };
const ctx = new (require('vm').createContext)({
  document: docStub, window: winStub, performance: { now: ()=>0 },
  requestAnimationFrame: ()=>0, Math, Float32Array, Array, JSON, console,
  AudioContext: undefined, setTimeout, setInterval, Infinity, String, Number, Object, parseInt, isFinite,
});
require('vm').runInContext(js.replace(/requestAnimationFrame\(gameLoop\);?\s*$/, ''), ctx);

// 1) Validar transcrição do mapa
const m = ctx.map, MW = ctx.MAP_W, MH = ctx.MAP_H;
console.log('== 1. MAPA ==');
console.log('Dimensões:', MW, 'x', MH);
let borderOk = true, diag = 0;
for (let x=0;x<MW;x++) if (m[0][x]===0 || m[MH-1][x]===0) borderOk=false;
for (let y=0;y<MH;y++) if (m[y][0]===0 || m[y][MW-1]===0) borderOk=false;
console.log('Bordas sólidas (24x24):', borderOk ? 'OK' : 'FALHOU');
// contagem de paredes vs abertos
let walls=0; for (let y=0;y<MH;y++) for (let x=0;x<MW;x++) if(m[y][x]!==0) walls++;
console.log('Células de parede:', walls, '/', MW*MH);

// 2) Células de spawn dos inimigos + jogador livres
console.log('\n== 2. SPAWNS ==');
const spawns = [[22,12,'player'] ,[5,2,'imp1'],[13,2,'imp2'],[20,6,'imp3'],[10,12,'imp4'],[4,18,'imp5'],[18,20,'imp6']];
let spawnOk = true;
for (const [x,y,n] of spawns) {
  const v = m[y][x]; const ok = v===0;
  if (!ok) spawnOk=false;
  console.log(`  ${n} (${x},${y}): ${ok?'LIVRE':'PAREDE('+v+')'}`);
}
console.log('Spawms livres (coordenadas .5 são em células validadas):', spawnOk?'OK':'VERIFICAR');

