function buildSprite(pal, rows) {
  const w = Math.max(...rows.map(r => r.length));
  const h = rows.length;
  const c = document.createElement("canvas");
  c.width = w; c.height = h;
  const g = c.getContext("2d");
  g.imageSmoothingEnabled = false;
  for (let y = 0; y < h; y++) {
    const row = rows[y];
    // Centraliza a linha na largura máxima — garante arte alinhada mesmo que
    // alguma linha da matriz tenha ficado com tamanho diferente na autoria.
    const padLeft = Math.floor((w - row.length) / 2);
