891:function shoot() {
function shoot() {
  if (gameOver) return;
  if (ammo <= 0) { playEmpty(); return; }

  ammo--;
  fireTimer = 0.14;
  playShot();

  // Encontra o imp mais próximo dentro da área de mira e sem parede no caminho
  const invDet = 1 / (player.planeX * player.dirY - player.dirX * player.planeY);
  let best = null, bestDist = Infinity;
  const center = W / 2;
  const tol = W * CONFIG.fireTolerance;

  for (const e of enemies) {
    if (e.dead) continue;
    const rx = e.x - player.x, ry = e.y - player.y;
    const tx = invDet * (player.dirY * rx - player.dirX * ry);
    const ty = invDet * (-player.planeY * rx + player.planeX * ry);
    if (ty <= 0.2) continue;                          // atrás / muito perto
    const screenX = (W / 2) * (1 + tx / ty);
    if (Math.abs(screenX - center) > tol) continue;   // fora da área de mira
    // Linha de visão: não pode haver parede entre o jogador e o imp
    if (ty < zbuffer[Math.floor(center)] && ty < bestDist) {
      best = e; bestDist = ty;
    }
  }

  if (best) {
    best.hp--;
    best.flash = 0.14;
    if (best.hp <= 0) { best.dead = true; kills++; }
  }
}

