import re
src = open('index.html', encoding='utf-8').read()

controller = '''
<script>
/* ============ MODO DEMO (auto-prévia) ============
   Dirige o jogo sozinho por timeline: anda, gira, atira.
   Também publica estado no titulo (p/ debug) e grava frames via hook. */
(function () {
  var T0 = performance.now();
  // timeline: [inicio, fim, acao]
  var plan = [
    [0.0, 2.4, "fwd"],    // anda p/ frente no corredor
    [2.4, 5.0, "right"],  // gira 90 graus
    [5.0, 7.0, "fwd"],    // avança
    [7.0, 7.6, "left"],   // reajusta
    [7.6, 9.2, "fwd"],    // aproxima da zona de tiros
    [3.0, 3.1, "shoot"],  // rajada de tiros
    [3.2, 3.3, "shoot"],
    [3.4, 3.5, "shoot"],
    [8.4, 8.5, "shoot"],
  ];
  // imp em frente ao jogador p/ a cena de tiro
  enemies[0].x = 22.2; enemies[0].y = 9.5; enemies[0].hp = 3;
  enemies[1].x = 13.4; enemies[1].y = 4.5; enemies[1].hp = 3;

  function drive(t) {
    keys.fwd = keys.back = keys.left = keys.right = false;
    for (var i = 0; i < plan.length; i++) {
      var a = plan[i];
      if (t >= a[0] && t < a[1]) {
        if (a[2] === "fwd") keys.fwd = true;
