937:function ensureAudio() {
let audioCtx = null;
function ensureAudio() {
  if (!audioCtx) {
    try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); }
    catch (e) { audioCtx = null; }
  }
  if (audioCtx && audioCtx.state === "suspended") audioCtx.resume();
}

function noiseBurst(duration, freq, vol, type) {
  ensureAudio();
  if (!audioCtx) return;
  const t = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = type || "sawtooth";
  osc.frequency.setValueAtTime(freq, t);
  gain.gain.setValueAtTime(vol, t);
  gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
  osc.connect(gain); gain.connect(audioCtx.destination);
  osc.start(t); osc.stop(t + duration);
}

function playShot()     { noiseBurst(0.12, 700, 0.25, "sawtooth"); noiseBurst(0.08, 180, 0.2, "square"); }
function playEmpty()    { noiseBurst(0.05, 900, 0.12, "square"); }
function playReload()   { noiseBurst(0.03, 500, 0.1, "square"); setTimeout(() => noiseBurst(0.05, 300, 0.1, "square"), 250); }

