    const step = CONFIG.moveSpeed * dt / len;
    const r = CONFIG.playerRadius;

    // Deslocamento no eixo X (com colisão)
    const nx = player.x + mx * step;
    if (!isWall(nx + Math.sign(mx) * r, player.y)) player.x = nx;
    // Deslocamento no eixo Y (com colisão) — separado p/ deslizar ao longo da parede
    const ny = player.y + my * step;
    if (!isWall(player.x, ny + Math.sign(my) * r)) player.y = ny;
  }

  // Rotação (A/D ou setas)
  let rot = 0;
  if (keys.left)  rot += CONFIG.rotSpeed * dt;
  if (keys.right) rot -= CONFIG.rotSpeed * dt;
  if (rot !== 0) {
    const cs = Math.cos(rot), sn = Math.sin(rot);
    const odx = player.dirX, ody = player.dirY;
    player.dirX = odx * cs - ody * sn;
    player.dirY = odx * sn + ody * cs;
    const opx = player.planeX, opy = player.planeY;
    player.planeX = opx * cs - opy * sn;
    player.planeY = opx * sn + opy * cs;
  }

  // Balanço da caminhada (só quando há deslocamento real)
  player.walking = moving && len > 0;
  if (player.walking) player.bobT += dt * 9;
}

