  ctx.fillRect(0, 0, W, VIEW_H / 2);

  // Chão: gradiente marrom escuro (cacheado)
  ctx.fillStyle = gradFloor;
  ctx.fillRect(0, VIEW_H / 2, W, VIEW_H / 2);
}

