const keys = {
  fwd: false, back: false, left: false, right: false,
};

const KEYMAP = {
  KeyW: "fwd", ArrowUp: "fwd",
  KeyS: "back", ArrowDown: "back",
  KeyA: "left", ArrowLeft: "left",
  KeyD: "right", ArrowRight: "right",
};

// Mouse look (Pointer Lock) — gira a câmera com o mouse quando ativo
let mouseLook = false;
let mousePitchAccum = 0;

function rotatePlayer(angle) {
  const cs = Math.cos(angle), sn = Math.sin(angle);
  const odx = player.dirX, ody = player.dirY;
  player.dirX = odx * cs - ody * sn;
  player.dirY = odx * sn + ody * cs;
  const opx = player.planeX, opy = player.planeY;
  player.planeX = opx * cs - opy * sn;
  player.planeY = opx * sn + opy * cs;
}

// Entra/sai do modo "olhar com o mouse" (pointer lock no canvas)
function toggleMouseLook() {
  if (mouseLook) {
    document.exitPointerLock && document.exitPointerLock();
    mouseLook = false;
  } else if (canvas.requestPointerLock) {
    try { canvas.requestPointerLock(); } catch (_) {}
  }
}

canvas.addEventListener("click", (_) => { if (!mouseLook) toggleMouseLook(); });
document.addEventListener("pointerlockchange", () => {
  mouseLook = document.pointerLockElement === canvas;
});
document.addEventListener("mousemove", (e) => {
  if (!mouseLook) return;
  rotatePlayer(e.movementX * CONFIG.mouseSens);
});
document.addEventListener("mousedown", (e) => {
  if (e.button === 0 && mouseLook) shoot();
});

window.addEventListener("keydown", (e) => {
  const k = KEYMAP[e.code];
  if (k) { keys[k] = true; e.preventDefault(); }
  // Espaço dispara (sem auto-repeat)
  if (e.code === "Space" && !e.repeat) { shoot(); e.preventDefault(); }
  // R recarrega
  if (e.code === "KeyR") { reload(); }
  // P pausa (apenas se não estiver em pointer lock, pois ESC sai do lock)
  if (e.code === "KeyP") { togglePause(); }
  // M alterna minimapa
  if (e.code === "KeyM") { showMap = !showMap; }
});
window.addEventListener("keyup", (e) => {
  const k = KEYMAP[e.code];
  if (k) keys[k] = false;
});
// Perde o estado das teclas ao sair da janela (evita "tecla presa")
window.addEventListener("blur", () => { keys.fwd = keys.back = keys.left = keys.right = false; });

