        var iz = cam.position.z + fwd.z*5;
        imp.x = ix; imp.z = iz;
        out.push('imp0 pos='+ix.toFixed(2)+','+iz.toFixed(2)+' hp='+imp.hp);
        // aplica mesma rotação yaw/pitch do jogo (norte = z menor no mapa)
