(function () {
  if (!new URLSearchParams(location.search).has("demo")) return;
  // timeline: [início, fim, ação]
  const plan = [
    [0.0, 2.2, "fwd"], [2.2, 4.6, "right"], [4.6, 6.6, "fwd"], [6.6, 7.2, "left"],
