  ];
  // imp em frente ao spawn (câmera olha -Z por padrão)
  enemies[0].x = 5.5; enemies[0].z = 2.5;
  enemies[1].x = 13.5; enemies[1].z = 2.5;

  const T0 = performance.now();
  let armed = 0;
  const iv = setInterval(() => {
    const t = (performance.now() - T0) / 1000;
    keys.fwd = keys.back = keys.left = keys.right = false;
    for (const a of plan) {
      if (t >= a[0] && t < a[1]) {
        if (a[2] === "fwd") keys.fwd = true;
        else if (a[2] === "right") keys.right = true;
        else if (a[2] === "left") keys.left = true;
        else if (a[2] === "shoot") { if (!a.state) { a.state = true; shoot(); } }
      }
    }
    if (t > 9.5) clearInterval(iv);
  }, 16);
})();
</script>

