/* =====================================================================
   MINIMAPA (tecla M)
   Desenha a planta do labirinto (escala suja 1 célula = 4px) sobre o
   canvas do HUD/3D no canto superior direito. Atualizado 1x ao abrir.
   ===================================================================== */
let showMap = false;

function toggleMinimap() {
  showMap = !showMap;
  const mm = document.getElementById("minimap");
  mm.style.display = showMap ? "block" : "none";
  if (showMap) drawMinimap();
}

function drawMinimap() {
  const mm = document.getElementById("minimap");
  const g = mm.getContext("2d");
  const SCALE = 4;                       // 1 célula = 4px (24*4=96px)
  g.imageSmoothingEnabled = false;
  g.clearRect(0, 0, mm.width, mm.height);
  // paredes
  for (let y = 0; y < MAP_H; y++) {
    for (let x = 0; x < MAP_W; x++) {
      g.fillStyle = map[y][x] ? "#3a4a6a" : "#141414";
      g.fillRect(x * SCALE, y * SCALE, SCALE, SCALE);
    }
  }
  // inimigos vivos
  g.fillStyle = "#e03131";
  for (const e of enemies) {
    if (e.dead) continue;
    g.fillRect(Math.floor(e.x * SCALE) - 2, Math.floor(e.y * SCALE) - 2, 4, 4);
  }
  // jogador (verde)
  g.fillStyle = "#7fd07f";
  g.fillRect(Math.floor(player.x * SCALE) - 2, Math.floor(player.y * SCALE) - 2, 4, 4);
}

