  for (const e of enemies) {
    if (e.dead) continue;
    const dx = camera.position.x - e.x;
    const dz = camera.position.z - e.z;
    const d = Math.hypot(dx, dz);

    // Avança em direção ao jogador se dentro do alcance de aggro,
    // parando na distância de ataque corpo-a-corpo.
    if (d > CONFIG.attackRange && d < CONFIG.aggroRange) {
      const step = Math.min(CONFIG.enemySpeed * dt, d - CONFIG.attackRange);
      const nx = e.x + (dx / d) * step;
      const nz = e.z + (dz / d) * step;
      const er = 0.35;   // "raio" de colisão do imp (não entra em paredes)
      if (!isWall(nx + Math.sign(dx) * er, e.z)) e.x = nx;
      if (!isWall(e.x, nz + Math.sign(dz) * er)) e.z = nz;
    }

    // Dano por contato (corpo-a-corpo)
    if (d < CONFIG.attackRange + 0.1) {
      hp = Math.max(0, hp - 22 * dt);
      updateHUD();
      if (hp <= 0) { gameOver = true; showOverlay("GAME OVER", "#e03131"); }
